insert into public.template_clauses (org_id, template_id, position, key, body, condition, default_condition, optional, default_enabled) values
  (null, '2d000000-0000-4000-8000-000000000001', 1, 'unit', 'استأجر {{unit_type_label}} رقم {{unit_labels}} لاستعماله {{purpose}}.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 2, 'rent', 'الإيجار الشهري المتفق عليه هو {{rent_amount}} دينار فقط {{rent_words}} دينار كويتي لا غير، تدفع في بداية كل شهر ميلادي.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 3, 'grace', 'يبدأ استحقاق الإيجار اعتبارًا من {{first_collection_date}}.', 'first_collection_date != start_date', null, true, true),
  (null, '2d000000-0000-4000-8000-000000000001', 4, 'term', 'مدة هذا العقد {{term_words}} تبدأ من {{start_date}} ويحق للطرف الثاني إخلاء العين المؤجرة بخطاب خطي قبلها ب{{notice_period_words}}.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 5, 'end', 'هذا العقد ينتهي بانتهاء المدة المذكورة في البند رقم ({{clause_ref:term}}) ما لم يوافق الطرفان على تجديده خطيًا.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 6, 'maintenance', 'يتعهد المستأجر بالمحافظة على سلامة ونظافة العين المؤجرة موضوع هذا العقد ويكون مسؤولًا عن كل ضرر فيه بما فيها التكييف والكهرباء والأدوات الصحية والأبواب والزجاج وغيرها ويتم تصليحه من حسابه الخاص.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 7, 'neighbors', 'يتعهد المستأجر بالمحافظة على علاقة حسن الجوار مع الآخرين وعدم عرقلة حركة المرور في العقار كله.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 8, 'utilities', 'دفع تأمين الكهرباء واستهلاك الكهرباء والماء من حساب {{utilities_party_label}} وحده.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 9, 'deposit', 'دفع الطرف الثاني مبلغ {{security_deposit_amount}} دينار ({{security_deposit_words}}) تأمينًا يرد عند انتهاء العقد وتسليم العين بحالتها بعد خصم أي مستحقات.', 'security_deposit_fils > 0', null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 10, 'no_changes', 'لا يحق للمستأجر أن يحدث أي تغيير أو وضع أي إعلان في العين المؤجرة إلا بموافقة خطية من المالك.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 11, 'no_assignment', 'لا يحق للمستأجر أن يتنازل عن كل أو بعض هذا العقد أو إدخال أي طرف آخر فيه إلا بالموافقة الخطية من المالك.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 12, 'jurisdiction', 'القضاء الكويتي هو الفصل في أي نزاع بين طرفي هذا العقد.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000001', 13, 'copies', 'حرر هذا العقد من نسختين وبين كل طرف نسخة منه.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 1, 'unit', 'استأجر الطرف الثاني {{unit_type_label}} رقم {{unit_labels}}{{#unit_paci}} الرقم الآلي للمحل: {{unit_paci}}{{/unit_paci}}.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 2, 'inspection', 'أقر الطرف الثاني بأنه عاين العين موضوع هذا العقد المعاينة التامة النافية للجهالة وقبلها وأقر أنها صالحة لحاجته ومزاولة عمله.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 3, 'rent', 'استأجر الطرف الثاني {{unit_type_label}} نظير إيجار شهري قيمته {{rent_amount}} دينار كويتي فقط {{rent_words}} دينار كويتي لا غير تدفع في بداية كل شهر ميلادي.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 4, 'term', 'مدة هذا العقد {{term_words}} تبتدئ في: {{start_date}}{{#auto_renew}}، تجدد تلقائيًا.{{/auto_renew}}{{^auto_renew}} وتنتهي في {{end_date}}.{{/auto_renew}}{{#free_months}} وقد منح الطرف الثاني {{free_months_words}} مجانًا ويبدأ استحقاق الإيجار في {{first_collection_date}}، وفي حال رغبة الطرف الثاني إخلاء العين المؤجرة قبل مضي سنة واحدة فإنه ملزم بسداد قيمة الأشهر المجانية التي تم منحها له في بداية هذا العقد.{{/free_months}}', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 5, 'purpose', 'أقر الطرف الثاني أنه استأجر العين موضوع هذا العقد لمزاولة: {{purpose}}، ولا يحق له تغيير هذا العمل إلا بالموافقة الخطية من الطرف الأول والجهات الرسمية.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 6, 'licenses', 'إن استخراج تراخيص مزاولة العمل لهذا العقد هي مسؤولية الطرف الثاني فقط ولا يتحمل الطرف الأول أية مسؤولية مادية أو أدبية إذا لم يتمكن المستأجر من الحصول عليها.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 7, 'utilities', '{{#utilities_owner}}دفع تأمين الكهرباء واستهلاك الكهرباء والماء من حساب الطرف الأول فقط{{#electricity_fixed_amount}} وقيمة استهلاك الكهرباء {{electricity_fixed_amount}} دينار شهريًا، {{electricity_fixed_words}}{{/electricity_fixed_amount}}.{{/utilities_owner}}{{^utilities_owner}}دفع تأمين الكهرباء واستهلاك الكهرباء والماء من حساب الطرف الثاني وحده.{{/utilities_owner}}', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 8, 'electric_load', 'لا يحق للطرف الثاني زيادة أحمال الكهرباء للمحل موضوع هذا العقد إلا بالموافقة الرسمية من وزارة الكهرباء مع تحمل الطرف الثاني جميع تكاليف زيادة هذه الأحمال من حسابه الخاص وحده.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 9, 'fresh_water', 'إذا رغب الطرف الثاني بتزويد العين موضوع هذا العقد بالماء العذب فإنه يتم الاتفاق على كمية وقيمة الاستهلاك شهريًا.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 10, 'industry_authority', 'في حال قررت الهيئة العامة للصناعة زيادة مبالغ مالية إيجارية على القسيمة فوق ما هو مقرر حين إبرام هذا العقد فإن الطرف الثاني قد وافق على أن يسدد ما يترتب عليه مقابل هذه الزيادة في حدود المساحة التأجيرية الخاصة به في هذا العقد.', null, 'property_type == ''industrial''', true, true),
  (null, '2d000000-0000-4000-8000-000000000002', 11, 'cleanliness', 'لا يحق للطرف الثاني وضع أي مواد أو بضائع أو مخلفات خارج حدود العين ويجب عليه المحافظة على النظافة العامة ومنطقة الخدمات والأدراج.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 12, 'fire_safety', 'لا يحق للطرف الثاني تخزين أية مواد قابلة للاشتعال داخل المحل أو خارجه ويلتزم بشروط الإدارة العامة للإطفاء ويتحمل وحده المسؤولية الكاملة عن مخالفة العقد.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 13, 'parking', 'لا يحق للطرف الثاني أن يستخدم مواقف سيارات المحلات الأخرى.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 14, 'roof', 'لا يحق للطرف الثاني استخدام أسطح القسيمة للتخزين أو خلافه دون الرجوع للطرف الأول وموافقته خطيًا.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 15, 'signage', 'لا يحق للطرف الثاني تركيب الإعلان الخاص به إلا في المكان المخصص له فقط وأي زيادة يحق للمالك إزالتها.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 16, 'structure', 'يتعهد الطرف الثاني بعدم إزالة أو إضافة مبانٍ أو منشآت في المحل إلا بالموافقة الخطية من الطرف الأول والجهات الرسمية المختصة.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 17, 'neighbors', 'يتعهد الطرف الثاني بالمحافظة على حسن الجوار وممتلكات الآخرين والخدمات العامة.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 18, 'no_assignment', 'لا يحق للطرف الثاني التنازل عن هذا العقد أو جزء منه أو إدخال طرف آخر به إلا بالموافقة الخطية من الطرف الأول.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 19, 'handover', 'في حال ترك الطرف الثاني المحل موضوع هذا العقد أو فسخه فإنه يتعهد أن يعيده كما كان حين استلمه.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 20, 'amendments', 'كل تغيير بهذا العقد وشروطه لا يعتد به إلا بالموافقة الخطية من الطرف الأول ويعتبر هذا العقد ملغيًا في حال مخالفة الطرف الثاني لأي من بنوده والتزاماته التعاقدية.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 21, 'termination_notice', 'إذا رغب الطرف الثاني في فسخ هذا العقد فيجب عليه إبلاغ الطرف الأول خطيًا وقبل {{notice_period_words}} من فسخ العقد.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 22, 'address', 'عنوان المراسلة لطرفي هذا العقد هو المسجل في البطاقة المدنية لكل منهما.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 23, 'annex', 'البنود التي لم يرد ذكرها في هذا العقد يتم التفاهم عليها في عقد ملحق لهذا العقد ويوقع من طرفي هذا العقد.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 24, 'jurisdiction', 'محاكم الكويت هي الفصل في أي نزاع قد ينشأ لا قدر الله.', null, null, false, true),
  (null, '2d000000-0000-4000-8000-000000000002', 25, 'no_worker_housing', 'سكن العمال وغيرهم ومبيتهم غير مسموح به بتاتًا في القسيمة موضوع هذا العقد.', null, null, false, true);
