  ('0a000000-0000-4000-8000-000000000001', 'مكتب الواحة لإدارة العقارات', 'Al Waha Property Management', '{"proration":false,"dueDay":1,"allocationStrategy":"fifo","receiptDuplicatePolicy":"warn","digits":"latn","letterhead":true,"poweredBy":true,"accent":"ink","voucherThresholdFils":500000,"lateReminderDays":[3,7,15,30],"numbering":{"contractResidential":"R","contractInvestment":"I","receipt":"RC","voucher":"EX"},"reminderTemplateAr":"السلام عليكم {{tenant_name}}،\nنود تذكيركم بوجود مبلغ مستحق قدره {{amount}} د.ك عن {{months}} للوحدة {{unit}} في {{property}}.\nنرجو التكرم بالسداد في أقرب وقت. شكرًا لكم.\n{{org_name}}","reminderTemplateEn":"Hello {{tenant_name}},\nThis is a friendly reminder that {{amount}} KWD is due for {{months}} for unit {{unit}} at {{property}}.\nThank you.\n{{org_name}}"}'::jsonb);
