  ('1a000000-0000-4000-8000-000000000001', '0a000000-0000-4000-8000-000000000001', 'R-2025-0001', 'residential', '2d000000-0000-4000-8000-000000000001', '0f000000-0000-4000-8000-000000000002', '0d000000-0000-4000-8000-000000000001', '0c000000-0000-4000-8000-000000000001', '2025-01-01', '2025-01-01', '2025-01-01', 60, '2029-12-31', false, 300000, 'سكن عائلي', 'owner', 0, 0, 2, 0, 'none', 'active', '{}'::jsonb, '{"preamble":["عقد إيجار","انه في يوم الأربعاء الموافق 01/01/2025","تم الاتفاق بين كل من:","الطرف الأول: عبدالعزيز محمد الصالح، المالك","ويحمل بطاقة مدنية رقم: 277040679195","الطرف الثاني: فهد جاسم العجمي، المستأجر","بطاقة مدنية: 279060498817، تليفون: 52285096","حيث إن الطرف الأول يستغل الجابرية قطعة 1 شارع 7 منزل 157 الرقم الآلي للعنوان 12045781","تم الاتفاق وذلك وفق الشروط التالية:"],"clauses":[{"number":1,"key":"unit","text":"استأجر شقة رقم واحد لاستعماله سكن عائلي."},{"number":2,"key":"rent","text":"الإيجار الشهري المتفق عليه هو 300.000 دينار فقط ثلاثمائة دينار كويتي لا غير، تدفع في بداية كل شهر ميلادي."},{"number":3,"key":"term","text":"مدة هذا العقد خمس سنوات تبدأ من 01/01/2025 ويحق للطرف الثاني إخلاء العين المؤجرة بخطاب خطي قبلها بشهرين."},{"number":4,"key":"end","text":"هذا العقد ينتهي بانتهاء المدة المذكورة في البند رقم (3) ما لم يوافق الطرفان على تجديده خطيًا."},{"number":5,"key":"maintenance","text":"يتعهد المستأجر بالمحافظة على سلامة ونظافة العين المؤجرة موضوع هذا العقد ويكون مسؤولًا عن كل ضرر فيه بما فيها التكييف والكهرباء والأدوات الصحية والأبواب والزجاج وغيرها ويتم تصليحه من حسابه الخاص."},{"number":6,"key":"neighbors","text":"يتعهد المستأجر بالمحافظة على علاقة حسن الجوار مع الآخرين وعدم عرقلة حركة المرور في العقار كله."},{"number":7,"key":"utilities","text":"دفع تأمين الكهرباء واستهلاك الكهرباء والماء من حساب الطرف الأول وحده."},{"number":8,"key":"no_changes","text":"لا يحق للمستأجر أن يحدث أي تغيير أو وضع أي إعلان في العين المؤجرة إلا بموافقة خطية من المالك."},{"number":9,"key":"no_assignment","text":"لا يحق للمستأجر أن يتنازل عن كل أو بعض هذا العقد أو إدخال أي طرف آخر فيه إلا بالموافقة الخطية من المالك."},{"number":10,"key":"jurisdiction","text":"القضاء الكويتي هو الفصل في أي نزاع بين طرفي هذا العقد."},{"number":11,"key":"copies","text":"حرر هذا العقد من نسختين وبين كل طرف نسخة منه."}],"closing":[]}'::jsonb, null),
